    public string Language { get; private set; } = "zh-CN";
    public bool IsEnglish => Language.StartsWith("en", StringComparison.OrdinalIgnoreCase);
    public event Action? Changed;
    public string Text(string key)
    {
        if (Entries.TryGetValue(key, out var value) || HomeEntries.TryGetValue(key, out value) || KittingEntries.TryGetValue(key, out value) || MaterialExecutionEntries.TryGetValue(key, out value) || OperationEntries.TryGetValue(key, out value) || OperationErrorEntries.TryGetValue(key, out value) || OperationActionEntries.TryGetValue(key, out value) || OperationWorkLogEntries.TryGetValue(key, out value) || QualityEntries.TryGetValue(key, out value) || QualityStandardEntries.TryGetValue(key, out value) || QualityDispositionEntries.TryGetValue(key, out value) || QualityDispositionValidationEntries.TryGetValue(key, out value) || QualityReportEntries.TryGetValue(key, out value) || QualityReceiptEntries.TryGetValue(key, out value) || FinishedGoodsReceiptEntries.TryGetValue(key, out value) || FinishedGoodsShipmentEntries.TryGetValue(key, out value) || AcceptanceEntries.TryGetValue(key, out value) || ServiceEquipmentEntries.TryGetValue(key, out value) || ServiceWorkOrderEntries.TryGetValue(key, out value) || ServiceWorkOrderPartEntries.TryGetValue(key, out value) || ServiceWorkOrderPartValidationEntries.TryGetValue(key, out value) || MaterialTransferEntries.TryGetValue(key, out value) || OperationStandardEntries.TryGetValue(key, out value) || OaOverviewEntries.TryGetValue(key, out value) || PmsOverviewEntries.TryGetValue(key, out value) || CommonOverviewEntries.TryGetValue(key, out value) || ModuleOverviewEntries.TryGetValue(key, out value)) return IsEnglish ? value.En : value.Zh;
        return key;
    }
    public void SetLanguage(string? language)
    {
        var next = string.Equals(language, "en-US", StringComparison.OrdinalIgnoreCase) ? "en-US" : "zh-CN";
        if (Language == next) return; Language = next; Changed?.Invoke();
    }
